<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;

/** Small internal test UI. Never renders passwords or retains submitted password values. */
final class MerchantProvisioningView
{
    private static function h(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES,'UTF-8');}
    public static function render(string $csrf,?array $receipt=null,string $error=''):string
    {
        $h=static fn($v)=>self::h($v);
        $html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Internal merchant provisioning</title><main data-onboarding-page><h1>Internal merchant provisioning</h1><p>Isolated synthetic testing only. Public registration is disabled. No email or SMS is sent.</p><a href="/merchant-dev.php">Operator dashboard</a>';
        if($error!=='')$html.='<p role="alert">'.$h($error).'</p>';
        if($receipt!==null){
            $html.='<section data-provisioning-confirmation data-merchant="'.$h($receipt['merchant_id']).'" data-status="'.$h($receipt['status']).'"><h2>Provisioning confirmation</h2><dl>';
            foreach(['business_name'=>'Business','business_type'=>'Business type','admin_contact'=>'Administrative contact','merchant_id'=>'Merchant ID','outlet_name'=>'Initial outlet','merchant_outlet_id'=>'Outlet ID','legacy_outlet_id'=>'Sign-in outlet number','owner_name'=>'Owner','owner_username'=>'Owner username','status'=>'Activation status','opening_time'=>'Scheduled opening','closing_time'=>'Scheduled closing'] as $key=>$label)$html.='<dt>'.$h($label).'</dt><dd>'.$h($receipt[$key]).'</dd>';
            $html.='</dl><p>Ordering remains CLOSED. No products, printers, financial grants or platform privileges were provisioned.</p>';
            if($receipt['status']==='pending_activation'){
                $html.='<h3>Attended synthetic owner activation</h3><p>The synthetic owner privately chooses a password here during the authorized administrator session. This is not an external invitation or production identity-verification process.</p><form method="post" id="owner-activation">';
                foreach(['_csrf'=>$csrf,'_ui'=>'1','action'=>'onboarding-activate','merchant_id'=>$receipt['merchant_id'],'version'=>$receipt['version'],'request'=>bin2hex(random_bytes(16))] as $key=>$value)$html.='<input type="hidden" name="'.$h($key).'" value="'.$h($value).'">';
                $html.='<label>New owner password <input type="password" name="password" autocomplete="new-password" minlength="14" maxlength="64" required></label><label>Confirm password <input type="password" name="confirmation" autocomplete="new-password" minlength="14" maxlength="64" required></label><button>Activate this synthetic owner</button></form>';
            }else{$html.='<p data-activation-complete>Activation complete. The owner can sign in through the normal development login using the outlet number and username above.</p>';}
            $html.='</section><a href="/merchant-dev.php?onboarding=1">New provisioning form</a>';
        }else{
            $html.='<h2>Create merchant, initial outlet and pending owner</h2><form method="post" id="merchant-provisioning">';
            foreach(['_csrf'=>$csrf,'_ui'=>'1','action'=>'onboarding-create','request'=>bin2hex(random_bytes(16))] as $key=>$value)$html.='<input type="hidden" name="'.$h($key).'" value="'.$h($value).'">';
            foreach(['business_name'=>['Business display name',200],'admin_contact'=>['Administrative email (synthetic)',254],'outlet_name'=>['Initial outlet name',160],'owner_name'=>['Synthetic owner display name',100],'owner_username'=>['Owner sign-in username',64]] as $key=>[$label,$max])$html.='<p><label>'.$h($label).' <input name="'.$h($key).'" maxlength="'.$max.'" required'.($key==='admin_contact'?' type="email"':'').'></label></p>';
            $html.='<p><label>Business type <select name="business_type"><option value="restaurant">Restaurant</option><option value="cafe">Cafe</option></select></label></p><p><label>Scheduled opening (IST) <input type="time" name="opening_time" value="08:00" required></label> <label>Scheduled closing (IST) <input type="time" name="closing_time" value="22:00" required></label></p><p>Identifiers and owner permissions are generated by the server. Account and merchant remain inactive until attended activation.</p><button>Create pending merchant</button></form>';
        }
        return $html.'</main></html>';
    }
}
